import{_ as d,C as o,o as u,c as w,j as t,a,E as s,a8 as g}from"./chunks/framework.27XeWUA0.js";const n="/schedule-dashboard/thumbs/yt/JGtkTjn4120-640.webp",m="/schedule-dashboard/thumbs/yt/JGtkTjn4120-1280.webp",r="/schedule-dashboard/thumbs/yt/prGP0huECPo-640.webp",b="/schedule-dashboard/thumbs/yt/prGP0huECPo-1280.webp",i="/schedule-dashboard/thumbs/yt/g_NgCLTibiM-640.webp",v="/schedule-dashboard/thumbs/yt/g_NgCLTibiM-1280.webp",l="/schedule-dashboard/thumbs/yt/XIHZpZtYCzo-640.webp",y="/schedule-dashboard/thumbs/yt/XIHZpZtYCzo-1280.webp",h="/schedule-dashboard/thumbs/yt/3Ad73Onx3Aw-640.webp",f="/schedule-dashboard/thumbs/yt/3Ad73Onx3Aw-1280.webp",j=JSON.parse('{"title":"AI Digest · Wed 04 Nov 2026","description":"","frontmatter":{"aside":false,"outline":false},"headers":[],"params":{"date":"2026-11-04","routine":"digest"},"relativePath":"digest/2026-11-04.md","filePath":"digest/[date].md"}'),k={name:"digest/2026-11-04.md"},_=n+" 640w, "+m+" 1280w",A=r+" 640w, "+b+" 1280w",C=i+" 640w, "+v+" 1280w",x=l+" 640w, "+y+" 1280w",T=h+" 640w, "+f+" 1280w",I={id:"ai-digest-·-wed-04-nov-2026",tabindex:"-1"};function P(G,e,N,M,E,Z){const c=o("Badge"),p=o("DayFilter");return u(),w("div",null,[t("h1",I,[e[0]||(e[0]=a("AI Digest · Wed 04 Nov 2026 ",-1)),s(c,{type:"tip",text:"5"}),e[1]||(e[1]=a()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#ai-digest-·-wed-04-nov-2026","aria-label":'Permalink to "AI Digest · Wed 04 Nov 2026 <Badge type="tip" text="5" />"'},"​",-1))]),e[3]||(e[3]=t("p",{class:"sub"},"AI Engineer daily digest — 4 Nov 2026 · run date Wed 04 Nov 2026 · 5 videos",-1)),e[4]||(e[4]=t("div",{class:"overview"},[t("p",null,[t("strong",null,"AI Engineer:"),a(` 5 new talks in the last 24 hours, all with full transcripts. The freshest and the one most worth your time is Basis co-founder Mitchell Troyanovsky (4 Nov, 12:00 AM IST) on why personal AI speed-ups don't reach companies, with behavior specs, forking and sub-agent simulations as practical tools. Artificial Analysis (3 Nov, 8:00 PM IST) has a useful breakdown of what one agent task costs ($21 with caching, over $200 without). Neo4j's graph-engineering talk partly retells an earlier Neo4j memory-to-skills talk, and Mixedbread's first half is the familiar "RAG is lossy" argument before its 36% to 98% hedge-fund result; Factory's in-VPC compute design is mainly for people deploying agents into enterprise clouds.`)]),t("p",null,[t("strong",null,"Better Stack:"),a(" nothing new in the last 24 hours.")])],-1)),s(p),e[5]||(e[5]=g('<div class="grid cards2"><article class="it full" id="v-JGtkTjn4120" data-title="Why AI Makes You 100x Faster but Not Your Company - Mitchell Troyanovsky, Basis" data-channel="AI Engineer" data-verdict="worth"><a class="th" href="https://www.youtube.com/watch?v=JGtkTjn4120" target="_blank" rel="noopener"><img src="'+n+'" srcset="'+_+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-worth">worth</span><h3><a href="https://www.youtube.com/watch?v=JGtkTjn4120" target="_blank" rel="noopener">Why AI Makes You 100x Faster but Not Your Company - Mitchell Troyanovsky, Basis</a></h3><div class="meta">AI Engineer · Mitchell Troyanovsky, Basis (co-founder) · uploaded 4 Nov, 12:00 AM IST · 19:13</div><div class="verdict v-worth"><b>Verdict:</b> worth watching — a clear, practical framework for production agents, with behavior specs, forking and simulations as takeaways you can use.</div><div class="repeat">🔁 Repeat: &#39;evals for agents&#39; — seen 53 times before, &#39;AI for finance&#39; 20 times, &#39;self-improving agents&#39; 19 times and &#39;agent reliability&#39; 4 times. New here: the &quot;competency gap vs process gap&quot; explanation of why personal AI speed-ups don&#39;t reach companies, behavior specs used as rubrics on trajectories with no ground truth, and cheap sub-agent &quot;simulations&quot; of your production agent.</div><div class="sh">Why companies haven&#39;t sped up</div><ul><li><strong>Firms run on process, not determinism:</strong> The head of an accounting firm trusts work he never sees because people follow processes, down to &quot;use the approved software to pull the bank data&quot;; Troyanovsky says his own output is up maybe 100x but a company&#39;s isn&#39;t (<a href="https://www.youtube.com/watch?v=JGtkTjn4120&amp;t=1s" target="_blank" rel="noopener">0:01</a>–<a href="https://www.youtube.com/watch?v=JGtkTjn4120&amp;t=244s" target="_blank" rel="noopener">4:04</a>)</li><li><strong>Two gaps in coding-style agents:</strong> A competency gap (users must manage skills, memories and a theory of mind of the agent, which most knowledge workers can&#39;t) and a process gap (each user customises how work is done, when process should come from leadership) (<a href="https://www.youtube.com/watch?v=JGtkTjn4120&amp;t=183s" target="_blank" rel="noopener">3:03</a>–<a href="https://www.youtube.com/watch?v=JGtkTjn4120&amp;t=364s" target="_blank" rel="noopener">6:04</a>)</li><li><strong>Be opinionated:</strong> Reading a PDF has endless options (VLM, open-source OCR, OCR plus 5 or 100 VLM checkers); an agent with no fixed opinion can&#39;t be reliable. Some opinions come from expertise, like reading the primary source for tax work or screenshotting a PowerPoint before returning it, and they trade off accuracy against latency (<a href="https://www.youtube.com/watch?v=JGtkTjn4120&amp;t=364s" target="_blank" rel="noopener">6:04</a>–<a href="https://www.youtube.com/watch?v=JGtkTjn4120&amp;t=547s" target="_blank" rel="noopener">9:07</a>)</li></ul><div class="sh">Getting signal beyond outcome evals</div><ul><li><strong>Outcome evals don&#39;t generalize:</strong> A few hundred or thousand graded cases can&#39;t cover hundreds of thousands of long production trajectories, so instead check whether the intended behavior shows up, e.g. a bank reconciliation that explains a difference rather than posting a plug entry to make it tie (<a href="https://www.youtube.com/watch?v=JGtkTjn4120&amp;t=547s" target="_blank" rel="noopener">9:07</a>–<a href="https://www.youtube.com/watch?v=JGtkTjn4120&amp;t=667s" target="_blank" rel="noopener">11:07</a>)</li><li><strong>Context is runtime training data:</strong> Behavior comes from the system prompt, progressive disclosure, tool descriptions and the model together, so care about every token, and write a &quot;behavior spec&quot; (a product spec for agents) of the opinions that matter most, used as a rubric on any trajectory: was the behavior relevant, and did the agent show it? (<a href="https://www.youtube.com/watch?v=JGtkTjn4120&amp;t=667s" target="_blank" rel="noopener">11:07</a>–<a href="https://www.youtube.com/watch?v=JGtkTjn4120&amp;t=804s" target="_blank" rel="noopener">13:24</a>)</li><li><strong>Forking:</strong> When a trajectory fails a behavior check, fork it just before the bad decision to ask the agent why or test a context change, which beats guessing among a thousand inference calls in a 5-hour run (<a href="https://www.youtube.com/watch?v=JGtkTjn4120&amp;t=804s" target="_blank" rel="noopener">13:24</a>–<a href="https://www.youtube.com/watch?v=JGtkTjn4120&amp;t=913s" target="_blank" rel="noopener">15:13</a>)</li><li><strong>Simulations:</strong> Ask a coding agent to spin up a sub-agent that pretends to be your production agent (same prompt and skills, told not to cheat) to replay a situation and test tweaks; he did this for a year and a half before Basis built forking (<a href="https://www.youtube.com/watch?v=JGtkTjn4120&amp;t=913s" target="_blank" rel="noopener">15:13</a>–<a href="https://www.youtube.com/watch?v=JGtkTjn4120&amp;t=1033s" target="_blank" rel="noopener">17:13</a>)</li></ul><div class="sh">Trust and scale</div><ul><li><strong>Earn trust like a coworker:</strong> You review a PR based on its blast radius and how competent the author is, and agents earn looser review the same way; nobody wants a &quot;move 37&quot; on their tax return, they want it done reliably (<a href="https://www.youtube.com/watch?v=JGtkTjn4120&amp;t=1033s" target="_blank" rel="noopener">17:13</a>–<a href="https://www.youtube.com/watch?v=JGtkTjn4120&amp;t=1152s" target="_blank" rel="noopener">19:12</a>)</li></ul></div></article><article class="it full" id="v-prGP0huECPo" data-title="Without Caching, Your AI Agent Costs 10x More - George Cameron, Artificial Analysis" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=prGP0huECPo" target="_blank" rel="noopener"><img src="'+r+'" srcset="'+A+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=prGP0huECPo" target="_blank" rel="noopener">Without Caching, Your AI Agent Costs 10x More - George Cameron, Artificial Analysis</a></h3><div class="meta">AI Engineer · George Cameron, Artificial Analysis (co-founder) · uploaded 3 Nov, 8:00 PM IST · 19:43</div><div class="verdict v-skim"><b>Verdict:</b> skim from 6:53 — the cost breakdown and the limited vs unlimited framing are new and useful; the landscape opening is familiar benchmark ground.</div><div class="repeat">🔁 Repeat: &#39;open source / local models&#39; — seen 50 times before, &#39;LLM releases / benchmarks&#39; 46 times, &#39;inference / serving&#39; 37 times and &#39;token costs / AI spend&#39; 18 times. New here: a step-by-step cost breakdown of a single agent task, showing caching and turn count matter more than output tokens, plus the &quot;limited vs unlimited intelligence&quot; way to pick a model.</div><div class="sh">The landscape</div><ul><li><strong>Intelligence Index:</strong> Artificial Analysis (50 people in San Francisco, 500+ models tracked) blends 10 evals covering knowledge work, scientific reasoning, coding and terminal use, and hallucination; Opus 5.5 currently leads, and Gemini models stand out at navigating complex spreadsheets (<a href="https://www.youtube.com/watch?v=prGP0huECPo&amp;t=167s" target="_blank" rel="noopener">2:47</a>–<a href="https://www.youtube.com/watch?v=prGP0huECPo&amp;t=325s" target="_blank" rel="noopener">5:25</a>)</li><li><strong>Pace and open weights (repeat):</strong> Frontier progress is accelerating, and open-weights models stay 3 to 9 months behind the leading closed models (<a href="https://www.youtube.com/watch?v=prGP0huECPo&amp;t=325s" target="_blank" rel="noopener">5:25</a>–<a href="https://www.youtube.com/watch?v=prGP0huECPo&amp;t=413s" target="_blank" rel="noopener">6:53</a>)</li></ul><div class="sh">What an agent task actually costs</div><ul><li><strong>Two orders of magnitude apart:</strong> Opus and Fable cost over $5 per task while models like GPT-6 Luna cost about 7 cents and still beat the original GPT-4; the price of reaching any given intelligence level drops about 10x a year (for example from just over $1 to about 10 cents) (<a href="https://www.youtube.com/watch?v=prGP0huECPo&amp;t=413s" target="_blank" rel="noopener">6:53</a>–<a href="https://www.youtube.com/watch?v=prGP0huECPo&amp;t=618s" target="_blank" rel="noopener">10:18</a>)</li><li><strong>Breaking down a $21 task:</strong> On their knowledge-work agent benchmark, Opus averages $21 per task: 165 steps at about 13 cents a call, with answer and reasoning tokens a tiny share; the big drivers are input tokens, cache-hit rate (cached input is about 10x cheaper) and number of turns (<a href="https://www.youtube.com/watch?v=prGP0huECPo&amp;t=618s" target="_blank" rel="noopener">10:18</a>–<a href="https://www.youtube.com/watch?v=prGP0huECPo&amp;t=779s" target="_blank" rel="noopener">12:59</a>)</li><li><strong>Caching is the whole game:</strong> With a 0% cache-hit rate, for example a self-hosted setup without prompt caching, the same task costs over $200; they&#39;ve started publishing cache-hit benchmarks for inference providers (<a href="https://www.youtube.com/watch?v=prGP0huECPo&amp;t=779s" target="_blank" rel="noopener">12:59</a>–<a href="https://www.youtube.com/watch?v=prGP0huECPo&amp;t=818s" target="_blank" rel="noopener">13:38</a>)</li><li><strong>Reasoning effort compounds:</strong> Higher effort adds turns and bloats message history, so Opus 5.5 ranges from about $1 per task at low effort to $21 at max; the open-weights GLM 5.3 Flash is far cheaper on every driver (<a href="https://www.youtube.com/watch?v=prGP0huECPo&amp;t=818s" target="_blank" rel="noopener">13:38</a>–<a href="https://www.youtube.com/watch?v=prGP0huECPo&amp;t=930s" target="_blank" rel="noopener">15:30</a>)</li></ul><div class="sh">Choosing a model</div><ul><li><strong>Limited vs unlimited intelligence tasks:</strong> &quot;Analyse my cost drivers&quot; always benefits from a smarter model, so set a budget; &quot;how much did I spend on subscriptions?&quot; gets the same $80 answer from cheap Luna and expensive Astra, so buy the cheapest model that clears the bar (<a href="https://www.youtube.com/watch?v=prGP0huECPo&amp;t=930s" target="_blank" rel="noopener">15:30</a>–<a href="https://www.youtube.com/watch?v=prGP0huECPo&amp;t=1092s" target="_blank" rel="noopener">18:12</a>)</li><li><strong>Shortlist, then benchmark your own:</strong> Read the Pareto curve, shortlist about five models and build your own benchmark for production; their new Optima product generates a benchmark from your uploaded context (<a href="https://www.youtube.com/watch?v=prGP0huECPo&amp;t=1092s" target="_blank" rel="noopener">18:12</a>–<a href="https://www.youtube.com/watch?v=prGP0huECPo&amp;t=1182s" target="_blank" rel="noopener">19:42</a>)</li></ul></div></article><article class="it full" id="v-g_NgCLTibiM" data-title="Make Your AI Agents Predictable With Graph Engineering - Zachary Blumenfeld, Neo4j" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=g_NgCLTibiM" target="_blank" rel="noopener"><img src="'+i+'" srcset="'+C+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=g_NgCLTibiM" target="_blank" rel="noopener">Make Your AI Agents Predictable With Graph Engineering - Zachary Blumenfeld, Neo4j</a></h3><div class="meta">AI Engineer · Zachary Blumenfeld, Neo4j · uploaded 3 Nov, 10:00 AM IST · 20:36</div><div class="verdict v-skim"><b>Verdict:</b> skim from 10:47 — the demo and timings are the new part; the memory-to-skill idea was covered in the earlier Neo4j talk.</div><div class="repeat">🔁 Repeat: &#39;agent memory&#39; — seen 17 times before and &#39;agent skills&#39; 16 times, including Will Lyon&#39;s 8 Oct Neo4j talk on turning agent memory into skills, which this partly retells. Also &#39;decision models&#39; 7 times and &#39;knowledge graphs&#39; 5 times. New here: the &quot;graph engineering&quot; framing and a loan-approval demo with measured speed-ups from a compiled, graph-shaped skill.</div><div class="sh">What graph engineering means</div><ul><li><strong>Three kinds of graph:</strong> Graph engineering (a term popularised by a Peter Steinberger tweet this summer) is designing agent work as an explicit graph; Blumenfeld splits it into execution graphs (LangGraph, ADK-style workflows), context graphs of past decision traces, and procedural graphs where a skill&#39;s steps are nodes (<a href="https://www.youtube.com/watch?v=g_NgCLTibiM&amp;t=1s" target="_blank" rel="noopener">0:01</a>–<a href="https://www.youtube.com/watch?v=g_NgCLTibiM&amp;t=184s" target="_blank" rel="noopener">3:04</a>)</li><li><strong>Why bother:</strong> Graphs give predictability (a constrained path), governance and auditing, and portability: stored next to your data in a knowledge layer, they can move between runtimes instead of living inside one framework (<a href="https://www.youtube.com/watch?v=g_NgCLTibiM&amp;t=184s" target="_blank" rel="noopener">3:04</a>–<a href="https://www.youtube.com/watch?v=g_NgCLTibiM&amp;t=363s" target="_blank" rel="noopener">6:03</a>)</li></ul><div class="sh">Skills compiled into graphs</div><ul><li><strong>Research result:</strong> A Neo4j workshop paper compiled skill files, scripts and references into a graph the agent must follow, and it raised task reward across physics, computer science and security tasks using smaller models such as Sonnet and now Haiku (<a href="https://www.youtube.com/watch?v=g_NgCLTibiM&amp;t=363s" target="_blank" rel="noopener">6:03</a>–<a href="https://www.youtube.com/watch?v=g_NgCLTibiM&amp;t=488s" target="_blank" rel="noopener">8:08</a>)</li><li><strong>Skills from memory (repeat):</strong> The same idea applied to the context graph distils a skill from past decision traces while keeping provenance, versioning and drift checks, in their reference Neo4j Agent Memory Service (<a href="https://www.youtube.com/watch?v=g_NgCLTibiM&amp;t=488s" target="_blank" rel="noopener">8:08</a>–<a href="https://www.youtube.com/watch?v=g_NgCLTibiM&amp;t=562s" target="_blank" rel="noopener">9:22</a>)</li><li><strong>Customer uses:</strong> Consultancies automate compliance audit reports for asset managers by resolving tickers and entities across databases, and Uber keeps region-by-region driver and vehicle regulation logic in configuration graphs (<a href="https://www.youtube.com/watch?v=g_NgCLTibiM&amp;t=562s" target="_blank" rel="noopener">9:22</a>–<a href="https://www.youtube.com/watch?v=g_NgCLTibiM&amp;t=647s" target="_blank" rel="noopener">10:47</a>)</li></ul><div class="sh">Loan-approval demo</div><ul><li><strong>Unconstrained agent:</strong> Asked whether to approve a loan for &quot;Rosa&#39;s Bakery&quot;, the agent crawls the business-plan PDF, Databricks transactions, lending policy and past decisions, but two runs take different-length paths and its approve or escalate confidence isn&#39;t calibrated (<a href="https://www.youtube.com/watch?v=g_NgCLTibiM&amp;t=647s" target="_blank" rel="noopener">10:47</a>–<a href="https://www.youtube.com/watch?v=g_NgCLTibiM&amp;t=870s" target="_blank" rel="noopener">14:30</a>)</li><li><strong>Compiled graph-shaped skill:</strong> Successful runs are compiled into a YAML graph skill run by a small CLI: hard policy rules in scripts, a typed decision model for the risk tier, a human-review router and a report-linting loop; runs are stored in the graph so you can see which branches were never taken (<a href="https://www.youtube.com/watch?v=g_NgCLTibiM&amp;t=870s" target="_blank" rel="noopener">14:30</a>–<a href="https://www.youtube.com/watch?v=g_NgCLTibiM&amp;t=1155s" target="_blank" rel="noopener">19:15</a>)</li><li><strong>Measured gains:</strong> Fable alone was right almost every time but took 2.7 minutes; the compiled procedure roughly halved that, and switching to Haiku cut it and the cost further, about half a minute to 2 minutes wall clock versus about 7.5 minutes before (<a href="https://www.youtube.com/watch?v=g_NgCLTibiM&amp;t=1155s" target="_blank" rel="noopener">19:15</a>–<a href="https://www.youtube.com/watch?v=g_NgCLTibiM&amp;t=1215s" target="_blank" rel="noopener">20:15</a>)</li></ul></div></article><article class="it full" id="v-XIHZpZtYCzo" data-title="Your AI Agents Shouldn&#39;t Care Where They Run - Nikhil Harithas, Factory" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=XIHZpZtYCzo" target="_blank" rel="noopener"><img src="'+l+'" srcset="'+x+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=XIHZpZtYCzo" target="_blank" rel="noopener">Your AI Agents Shouldn&#39;t Care Where They Run - Nikhil Harithas, Factory</a></h3><div class="meta">AI Engineer · Nikhil Harithas, Factory (head of forward-deployed engineering) · uploaded 3 Nov, 9:00 AM IST · 17:13</div><div class="verdict v-skim"><b>Verdict:</b> skim from 4:26 — worth it if you deploy agents into enterprise clouds; otherwise the sandbox and identity points are familiar.</div><div class="repeat">🔁 Repeat: &#39;AI in regulated industries&#39; — seen 22 times before, &#39;sandboxes for agents&#39; 20 times, &#39;software factory&#39; 16 times, &#39;agent identity&#39; 9 times and &#39;forward-deployed engineering&#39; 4 times. New here: the actual design of Factory&#39;s soon-to-be-open-sourced Open Compute layer (gateway, relay, drivers) for running agents inside a customer&#39;s own cloud.</div><div class="sh">The Blackstone problem</div><ul><li><strong>None of the defaults worked:</strong> Blackstone, with about a trillion dollars in assets, couldn&#39;t run agents on laptops and wanted its own compute, inference and identity, single-tenant everywhere, for Jira or Slack tickets delegated to Factory&#39;s coding agent Droid (<a href="https://www.youtube.com/watch?v=XIHZpZtYCzo&amp;t=12s" target="_blank" rel="noopener">0:12</a>–<a href="https://www.youtube.com/watch?v=XIHZpZtYCzo&amp;t=164s" target="_blank" rel="noopener">2:44</a>)</li><li><strong>Agents can&#39;t keep borrowing your identity:</strong> The recurring questions were whom an agent acts for and where it runs; Harithas argues agents are just slightly non-deterministic applications and should use the same identity and deployment patterns as other software (<a href="https://www.youtube.com/watch?v=XIHZpZtYCzo&amp;t=134s" target="_blank" rel="noopener">2:14</a>–<a href="https://www.youtube.com/watch?v=XIHZpZtYCzo&amp;t=266s" target="_blank" rel="noopener">4:26</a>)</li></ul><div class="sh">How Open Compute works</div><ul><li><strong>A separate compute plane:</strong> Installing an agent on a machine wasn&#39;t enough, because customers still had to manage the compute lifecycle, so Factory built Open Compute to handle it for any agent, on EC2, Kubernetes, micro-VMs or sandbox providers such as Daytona or Modal (<a href="https://www.youtube.com/watch?v=XIHZpZtYCzo&amp;t=266s" target="_blank" rel="noopener">4:26</a>–<a href="https://www.youtube.com/watch?v=XIHZpZtYCzo&amp;t=377s" target="_blank" rel="noopener">6:17</a>)</li><li><strong>Gateway, drivers and relay:</strong> A session request goes to Factory&#39;s compute gateway, which asks the Open Compute controller in the customer&#39;s VPC to start a machine through a driver (one per compute type); the machine then opens an outbound websocket to Factory&#39;s relay, so no inbound connection is ever needed, which security teams prefer (<a href="https://www.youtube.com/watch?v=XIHZpZtYCzo&amp;t=377s" target="_blank" rel="noopener">6:17</a>–<a href="https://www.youtube.com/watch?v=XIHZpZtYCzo&amp;t=559s" target="_blank" rel="noopener">9:19</a>)</li><li><strong>Bring your own key:</strong> Model calls can go through the customer&#39;s own deal, for example Bedrock, so the non-deterministic part of the loop and its blast radius stay inside the VPC (<a href="https://www.youtube.com/watch?v=XIHZpZtYCzo&amp;t=559s" target="_blank" rel="noopener">9:19</a>–<a href="https://www.youtube.com/watch?v=XIHZpZtYCzo&amp;t=681s" target="_blank" rel="noopener">11:21</a>)</li></ul><div class="sh">Open source and the hard parts</div><ul><li><strong>Computers, not sessions:</strong> Open-sourcing is planned &quot;in a few weeks&quot;; the unit is a computer with pause, resume, snapshot and fork (useful for handing subtasks to sub-agents), and snapshots and secrets can live in the customer&#39;s own S3 and secret store (<a href="https://www.youtube.com/watch?v=XIHZpZtYCzo&amp;t=681s" target="_blank" rel="noopener">11:21</a>–<a href="https://www.youtube.com/watch?v=XIHZpZtYCzo&amp;t=862s" target="_blank" rel="noopener">14:22</a>)</li><li><strong>Lifecycle bookkeeping:</strong> Dropped acks, routing users to the right sandbox and AWS micro-VMs&#39; 8-hour cap (their multi-day &quot;missions&quot; must snapshot and rehydrate in place) are the hard parts; new drivers are easy because Droid can write one straight from the spec (<a href="https://www.youtube.com/watch?v=XIHZpZtYCzo&amp;t=862s" target="_blank" rel="noopener">14:22</a>–<a href="https://www.youtube.com/watch?v=XIHZpZtYCzo&amp;t=1033s" target="_blank" rel="noopener">17:13</a>)</li></ul></div></article><article class="it full" id="v-3Ad73Onx3Aw" data-title="Better Search Took This AI Agent From 36% to 98% Accuracy - Aamir Shakir, Mixedbread" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=3Ad73Onx3Aw" target="_blank" rel="noopener"><img src="'+h+'" srcset="'+T+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=3Ad73Onx3Aw" target="_blank" rel="noopener">Better Search Took This AI Agent From 36% to 98% Accuracy - Aamir Shakir, Mixedbread</a></h3><div class="meta">AI Engineer · Aamir Shakir, Mixedbread · uploaded 3 Nov, 8:00 AM IST · 16:30</div><div class="verdict v-skim"><b>Verdict:</b> skim from 9:04 — a vendor pitch whose new parts are the multi-vector model and the hedge-fund numbers; the RAG critique is well-worn.</div><div class="repeat">🔁 Repeat: &#39;AI for finance&#39; — seen 20 times before, &#39;RAG vs long context&#39; 12 times, &#39;multimodal models&#39; 8 times and &#39;agentic search&#39; 7 times. New here: Mixedbread&#39;s multi-vector (late-interaction) retrieval model and a hedge-fund case going from 36% to 98% answer accuracy; the &quot;RAG is lossy&quot; first half is familiar.</div><div class="sh">Why agents fail to find things</div><ul><li><strong>Grep doesn&#39;t scale:</strong> An analyst asking why Intel&#39;s new GPU uses LPDDR5 instead of HBM memory gets so many lexical hits that the agent reads every document, which Shakir says can push a basic query to $10–$20, and scanned or binary PDFs can&#39;t be grepped at all (<a href="https://www.youtube.com/watch?v=3Ad73Onx3Aw&amp;t=90s" target="_blank" rel="noopener">1:30</a>–<a href="https://www.youtube.com/watch?v=3Ad73Onx3Aw&amp;t=240s" target="_blank" rel="noopener">4:00</a>)</li><li><strong>The &quot;Frankenstein stack&quot; (repeat):</strong> OCR or transcription, chunking, a single-vector embedding, a vector database and a reranker each lose information, need a vendor each, and take 6–8 months and 4–5 people to stand up (<a href="https://www.youtube.com/watch?v=3Ad73Onx3Aw&amp;t=240s" target="_blank" rel="noopener">4:00</a>–<a href="https://www.youtube.com/watch?v=3Ad73Onx3Aw&amp;t=362s" target="_blank" rel="noopener">6:02</a>)</li><li><strong>One point per page fails at scale (repeat):</strong> Nvidia&#39;s 1996 and 2026 earnings filings embed to nearly the same point, so quality is fine at tens of documents but degrades in production, and agents compensate by spawning sub-agents and burning context (<a href="https://www.youtube.com/watch?v=3Ad73Onx3Aw&amp;t=362s" target="_blank" rel="noopener">6:02</a>–<a href="https://www.youtube.com/watch?v=3Ad73Onx3Aw&amp;t=544s" target="_blank" rel="noopener">9:04</a>)</li></ul><div class="sh">What Mixedbread built</div><ul><li><strong>Multi-vector retrieval:</strong> Retrieval barely moved from BM25 (1994) until 2022 embeddings, then improved slowly; their new model, out &quot;next week&quot;, creates many contextualised embeddings per page (net income, revenue, all tagged as Nvidia) from screenshots, while still returning OCR and layout (<a href="https://www.youtube.com/watch?v=3Ad73Onx3Aw&amp;t=544s" target="_blank" rel="noopener">9:04</a>–<a href="https://www.youtube.com/watch?v=3Ad73Onx3Aw&amp;t=668s" target="_blank" rel="noopener">11:08</a>)</li><li><strong>Demo on Intel reports:</strong> A query for Intel Foundry&#39;s Q2 2025 operating margin finds the right chart page with bounding boxes for citations, normally in under 20 ms; a qualitative question triggers their agentic-search model &quot;Toast 1&quot;, which they claim matches Astra and Fable while being 40x faster and cheaper (<a href="https://www.youtube.com/watch?v=3Ad73Onx3Aw&amp;t=668s" target="_blank" rel="noopener">11:08</a>–<a href="https://www.youtube.com/watch?v=3Ad73Onx3Aw&amp;t=897s" target="_blank" rel="noopener">14:57</a>)</li></ul><div class="sh">Result</div><ul><li><strong>36% to 98%:</strong> A large hedge fund with over a billion documents, onboarded in about a week and a half, went from 36% to 98% expert-graded answer accuracy after replacing its chunking and vector-database stack, and used about 3x fewer LLM tokens (<a href="https://www.youtube.com/watch?v=3Ad73Onx3Aw&amp;t=897s" target="_blank" rel="noopener">14:57</a>–<a href="https://www.youtube.com/watch?v=3Ad73Onx3Aw&amp;t=989s" target="_blank" rel="noopener">16:29</a>)</li></ul></div></article></div>',1))])}const L=d(k,[["render",P]]);export{j as __pageData,L as default};
